def find_index_of_sequence(data: Any, sequence: Any, startindex: Any = 0) -> object {
    index = startindex;
    for token in sequence {
        index = data.find(token, index);
        if (index == -1) {
            return -1;
        }
    }
    return (index + len(sequence[-1]));
}

